import pytest

from pytmc import parser
from pytmc.bin.pragmalint import lint_expand_names_consistency, lint_source


def make_pragma(text):
    "Make a multiline pytmc pragma"
    return (
        """\
{attribute 'pytmc' := '
%s
'}"""
        % text
    )


def make_source(pragma, variable, type):
    """
    Make a wrapper for a pragma'd variable, to be used with `lint_source`
    """

    source = f"""
{make_pragma(pragma)}
{variable} : {type};
"""

    class Wrapper:
        _source = source
        name = "source-wrapper"
        tag = "ST"

        def find(cls):
            if cls is parser.Declaration:
                yield Decl

    class Decl:
        parent = Wrapper
        text = source
        tag = "Decl"

    return Wrapper


def make_source_param(pragma, variable="VAR", type="INT", **param_kw):
    "Make a pytest.param for use with `lint_source`"
    wrapper = make_source(pragma, variable, type)
    identifier = repr(wrapper._source)
    return pytest.param(wrapper, id=identifier, **param_kw)


@pytest.mark.parametrize(
    "source",
    [
        make_source_param("pv: test"),
        make_source_param("pv: test; io: io"),
        make_source_param("pv: test;; io: io"),
        make_source_param("pv: test\r\n\r io: io"),
        # Valid I/O types
        make_source_param("pv: test; io: i"),
        make_source_param("pv: test; io: o"),
        make_source_param("pv: test; io: io"),
        make_source_param("pv: test; io: input"),
        make_source_param("pv: test; io: output"),
        make_source_param("pv: test; io: rw"),
        make_source_param("pv: test; io: ro"),
        # Bad IO type
        make_source_param("io: foobar", marks=pytest.mark.xfail),
        # Missing delimiters
        make_source_param("pv: test io: test", marks=pytest.mark.xfail),
        make_source_param("pv: test test", marks=pytest.mark.xfail),
        # No PV
        make_source_param("io: io", marks=pytest.mark.xfail),
        make_source_param("abc", marks=pytest.mark.xfail),
        # $ character....
        make_source_param("pv: $(TEST)", marks=pytest.mark.xfail),
        # Update rates
        make_source_param("pv: test; update: 1HZ poll"),
        make_source_param("pv: test; update: 1s poll"),
        make_source_param("pv: test; update: 1HZ    notify"),
        make_source_param("pv: test; update:  1s  notify"),
        make_source_param("pv: test; update:  1HZ"),
        make_source_param("pv: test; update: 1s"),
        make_source_param("pv: test; update: 100es", marks=pytest.mark.xfail),
        make_source_param("pv: test; update: 1s test", marks=pytest.mark.xfail),
        make_source_param("pv: test; update: notify 1s", marks=pytest.mark.xfail),
        make_source_param("pv: test; field: SCAN I/O Intr"),
        make_source_param("pv: test; field: SCAN 1 second", marks=pytest.mark.xfail),
        # Archiver settings
        make_source_param("pv: test; archive: no"),
        make_source_param("pv: test; archive: 1s"),
        make_source_param("pv: test; archive: 1s"),
        make_source_param("pv: test; archive: 1s scan"),
        make_source_param("pv: test; archive: 1s monitor"),
        make_source_param("pv: test; archive: 1Hz scan"),
        make_source_param("pv: test; archive: 1Hz monitor"),
        make_source_param("pv: test; archive: 1Hz test", marks=pytest.mark.xfail),
        make_source_param("pv: test; archive: 1s test", marks=pytest.mark.xfail),
        make_source_param("pv: test; archive: 1Hz test", marks=pytest.mark.xfail),
        make_source_param("pv: test; archive: 1es", marks=pytest.mark.xfail),
        # Link settings
        make_source_param("pv: test; link: OTHER:PV"),
        make_source_param("pv: test; io: ro; link: OTHER:PV", marks=pytest.mark.xfail),
        make_source_param("pv: test; link: SPACES IN PV", marks=pytest.mark.xfail),
    ],
)
def test_lint_pragma(source):
    print("Linting source:")
    print(source._source)
    for info in lint_source("filename", source, verbose=True):
        if info.exception:
            raise info.exception


def _make_drift_source(decl_text):
    """Wrapper that yields a single Declaration containing `decl_text`.

    Mirrors the duck-typed Wrapper/Decl shape used by `make_source`,
    but takes the full multi-pragma decl body in one piece because
    drift detection is inherently about siblings inside one VAR block.
    """
    class Wrapper:
        name = "source-wrapper"
        tag = "ST"

        def find(cls):
            if cls is parser.Declaration:
                yield Decl

    class Decl:
        parent = Wrapper
        text = decl_text
        tag = "Decl"

    return Wrapper


def test_drift_two_siblings_reordered_flagged():
    """Two siblings with reordered same-length lists each emit a warning."""
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: STATE
    expand-names: MMS, CLZ, CLF, YAG
    '}
    afbMotorsNC : ARRAY[1..4] OF FB_MotionStageNC;

    {attribute 'pytmc' := '
    pv: POSITION
    expand-names: CLZ, MMS, CLF, YAG
    '}
    astPositionState : ARRAY[1..4] OF ST_PositionState;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert len(warnings) == 2
    assert all(w.exception is None for w in warnings)
    assert all("expand-names drift" in w.warning for w in warnings)


def test_drift_identical_siblings_not_flagged():
    """Two siblings with identical name lists are silent."""
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: STATE
    expand-names: MMS, CLZ, CLF, YAG
    '}
    afbMotorsNC : ARRAY[1..4] OF FB_MotionStageNC;

    {attribute 'pytmc' := '
    pv: POSITION
    expand-names: MMS, CLZ, CLF, YAG
    '}
    astPositionState : ARRAY[1..4] OF ST_PositionState;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert warnings == []


def test_drift_different_lengths_not_compared():
    """Siblings with different-length lists are not flagged.

    Different lengths represent different things and aren't comparable;
    each pragma's own length validation is a separate concern.
    """
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: STATE
    expand-names: MMS, CLZ, CLF, YAG
    '}
    afbMotorsNC : ARRAY[1..4] OF FB_MotionStageNC;

    {attribute 'pytmc' := '
    pv: AUX
    expand-names: A, B
    '}
    auxMotors : ARRAY[1..2] OF FB_AuxMotor;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert warnings == []


def test_drift_solo_pragma_not_flagged():
    """A single expand-names pragma has nothing to drift against."""
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: STATE
    expand-names: MMS, CLZ, CLF, YAG
    '}
    afbMotorsNC : ARRAY[1..4] OF FB_MotionStageNC;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert warnings == []


def test_drift_three_siblings_reports_each_offender():
    """When >2 siblings disagree, every offending site gets a warning."""
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: A
    expand-names: MMS, CLZ, CLF, YAG
    '}
    a : ARRAY[1..4] OF SOMETYPE;

    {attribute 'pytmc' := '
    pv: B
    expand-names: MMS, CLZ, CLF, YAG
    '}
    b : ARRAY[1..4] OF SOMETYPE;

    {attribute 'pytmc' := '
    pv: C
    expand-names: MMS, CLZ, YAG, CLF
    '}
    c : ARRAY[1..4] OF SOMETYPE;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert len(warnings) == 3


def test_drift_no_expand_names_anywhere_silent():
    """Sources without any expand-names pragmas produce no warnings."""
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: M1
    io: i
    '}
    var1 : INT;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert warnings == []


def test_drift_warning_carries_filename_and_line():
    """Yielded info objects carry filename, tag, and a usable line number."""
    src = _make_drift_source("""
    {attribute 'pytmc' := '
    pv: STATE
    expand-names: A, B
    '}
    a : ARRAY[1..2] OF X;

    {attribute 'pytmc' := '
    pv: POS
    expand-names: B, A
    '}
    b : ARRAY[1..2] OF X;
    """)
    warnings = list(lint_expand_names_consistency("file.TcPOU", src))
    assert len(warnings) == 2
    for w in warnings:
        assert w.filename == "file.TcPOU"
        assert w.tag == "ST"
        assert w.line_number is not None
        assert w.line_number > 0
